&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;6m4ee-0-0&quot;&gt;&lt;span data-offset-key=&quot;6m4ee-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Experience working self-driven and self-organizing.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;82h45&quot; data-offset-key=&quot;f407l-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;f407l-0-0&quot;&gt;&lt;span data-offset-key=&quot;f407l-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Excellent spoken and written communication skills in English.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
